-- Scoped one-time content repair; abort if an author edited a target after review.
begin;
lock table public.techniques in share row exclusive mode;
do $repair$
begin
 if (select count(*) from jsonb_to_recordset('[{"id":"master336-309","title":"進んだ道を正解にする覚悟を持つ","essence":"選択の正解は、選んだ瞬間より、その後どう生きたかで変わる。","explanation":"行ってみたい場所や始めたいことを思いついても、「もう少し落ち着いたら」と予定に入れないまま、半年や一年が過ぎることがある。その間に仕事が忙しくなったり、体力が落ちたり、相手の都合が変わったりして、当時なら簡単だったことが難しくなる。先送りは単に時期をずらすだけではなく、「未来も今と同じ条件で動ける」と見積もる行為でもある。やりたいことほど、実行できる条件が残っているうちに扱う必要がある。\n旅行へ行きたいなら、「いつか行く」と残さず、まず候補月を一つ決めて予定表に入れる。友人と一緒に行きたいなら、全員の生活が変わりそうな時期より前を優先する。資格取得や趣味でも、期間限定の講座や年齢、季節に左右されるものがあるなら、それを先に置く。反対に、いつでも始められるものは後へ回してもよい。全部を同時に始めるのではなく、期限のあるものから日程に変えていく。\nやりたいことを考えるときは、「どれが一番魅力的か」だけでなく、「どれは今を逃すと条件が変わるか」を見るとよい。まず一つだけ日程化し、期限の近いものを先に置く。そのうえで、他の希望は順番をつけて残せばいい。思いつくたびに全部始めれば時間もお金も足りなくなるが、何も決めなければ「いつか」のまま消える。未来の自分に丸投げせず、今の条件でできるものを一つ予定へ移すことが、先送りを減らす基準になる。","status":"published","access_tier":"complete","updated_at":"2026-09-03 02:29:20.892534+00"},{"id":"master336-310","title":"過去の自分を今の情報だけで裁かない","essence":"今なら分かることを、当時の自分も知っていた前提で責めるのはフェアではない。","explanation":"集団の中では普通に話せているのに、会が終わると「誰とも特別に近くなれていない」と感じることがある。全体の場だけで接していると、関係は集団がある時にしか機能しにくい。反対に、一人ずつ短い会話を重ねると、「この人とは個別にも話せる」という接点が増える。その接点が複数できるほど、集団の中で自分を知っている人が増え、居場所も一つの空気ではなく具体的な人間関係に支えられる。\n活動の帰り道で隣になった人に「今日のあれ、どう思いました？」と話しかけたり、作業中に別の人へ短く声をかけたりする。大勢の前では話しにくいことでも、一対一なら相手の考えや好みを知りやすい。次に集まった時には、目が合えば自然に話せる相手が何人かいる状態になる。誰か一人だけと親しくなるより、複数の相手との小さな関係を持つ方が、集団全体にも入りやすくなる。\n集団に馴染もうとするときは、「全体で盛り上がれているか」だけでなく、「個別に話せる相手が何人いるか」を見るとよい。帰り道や作業の合間を使い、一人ずつ短い接点を増やす。ただし、親しい人だけで固まり、他の人を遠ざければ派閥になってしまう。特定の一人に依存せず、複数の人とそれぞれ細い関係を結ぶことが、集団の中に安定した居場所を作る基準になる。","status":"published","access_tier":"complete","updated_at":"2026-10-01 19:02:55.898735+00"},{"id":"master336-337","title":"相手の話を自分の話で上書きしない","essence":"共感のつもりでも、毎回自分の話に置き換えると相手は話す気を失う。","explanation":"似た経験を返すこと自体は共感になり得る。しかし、相手が話し終える前に「私も」と主語を奪い、そのまま自分の体験を長く語ると、相手の出来事は自分語りの入口として扱われる。相手は聞いてもらうために話したのに、今度は聞き役と反応役を担わされるため、理解されなかった寂しさと感情労働が同時に残る。\n友人が仕事の失敗を話したときは、似た失敗をすぐ披露するより、「それは焦るよね」「その後どうなった？」と相手の話を一段深くする。自分の経験が役立ちそうなら、「似たことがあったけど、聞く？」と許可を取り、短く話した後で相手へ主語を返す。経験の類似より、いま誰の話をしているかを守る方が共感は伝わる。\n自分の話を一切しない必要はない。自己開示の往復は親しさをつくるが、相手の話を受け止める前に交代すると、会話の中心を競う形になる。まず内容や感情を言い換えて理解を確かめ、相手が話し切った合図を待つ。自分の体験は相手の理解を助ける分だけに留め、最後は質問や一言で相手へ戻す。","status":"draft","access_tier":"free","updated_at":"2026-09-04 14:51:17.35991+00"},{"id":"master336-338","title":"勝てる話でも勝ちにいかない","essence":"会話で優位を示すほど、相手には比較された感覚が残る。","explanation":"知識、収入、経験、人脈などで自分が上だと示せる場面はある。そこで訂正や追加情報を重ねて勝つと、事実上は正しくても、会話の目的が交流から順位決めへ変わる。相手は内容を楽しむ代わりに、自分の不足を見せないよう発言を選び、次の反論に備える。小さな優越の積み重ねが、対等に話せない警戒と比較疲れを残す。\n相手が「最近五キロ走れるようになった」と喜んでいるとき、自分の十キロ記録や速い友人の話を足す必要はない。「続けたのがすごいね」と、その人の変化の中で受け取る。誤情報を直す必要がある場合も、「正確にはこうらしいよ」と論点だけを整え、自分の知識量や経歴まで証拠として並べない。勝てる材料と、いま使うべき材料は別である。\n譲ることは、意見を隠したり事実を曲げたりすることではない。安全や重要な判断に関わる誤りは伝えてよいが、相手より上に立つことが目的へ混ざっていないかを確かめる。会話の後に相手が情報だけでなく尊厳も持ち帰れる形を選ぶ。正しさを共有財産にできれば、知識差は上下関係に変わらない。","status":"draft","access_tier":"free","updated_at":"2026-09-04 14:51:17.35991+00"},{"id":"master336-339","title":"褒められたら否定せず受け取る","essence":"褒め言葉を反射的に否定すると、相手にもう一度肯定する役割を負わせる。","explanation":"「そんなことない」と謙遜するつもりでも、褒めた側には、自分の観察や好意を否定された形が残る。さらに相手は「本当にそう思うよ」と根拠を足し、落ち込んだこちらを励ます役まで引き受けやすい。褒め言葉のたびにこの往復が起きると、好意を渡した人が自己評価を修復する係になり、短い会話にも余分な感情労働が生まれる。\n「その服似合うね」と言われたら、「ありがとう、気に入っているんだ」で十分である。仕事を褒められたときも、「まだまだです」と打ち消す代わりに、「見てくれてありがとう。そこは時間をかけた」と受け取る。照れがあるなら「うれしい、少し照れる」と感情を添えればよく、自分の欠点を持ち出して相手に再評価を求めなくてよい。\n受け取ることは、自分を大きく見せることでも、評価に全面同意することでもない。相手が差し出した好意を、訂正せずに着地させる行為である。共同の成果なら関係者の貢献を添えてよいが、それも自分への言葉を消した後ではなく、まず感謝してから行う。好意が一往復で完了すると、相手は安心してまた言葉を渡せる。","status":"draft","access_tier":"free","updated_at":"2026-09-04 14:51:17.35991+00"},{"id":"master336-340","title":"自慢話は短く終える","essence":"うれしい報告でも、実績や周囲の評価を重ねるほど相手に称賛役を求める形になる。","explanation":"達成を共有することは自然だが、数字、肩書、周囲の反応を次々に足すと、相手には適切な称賛を出し続ける役割が生まれる。話を止めれば嫉妬と思われそうで、薄い反応ならさらに説明されそうだと感じるため、聞き手は本音より安全な相づちを選ぶ。喜びの共有が一方向の自己呈示になると、比較と反応管理の疲れを残す。\n昇進や受賞を話すなら、「うれしかった。手伝ってくれた人にも感謝している」までで一度止める。相手が詳しく聞けば背景を話し、そうでなければ「最近そっちはどう？」と会話を戻す。SNSの反応や他人からの絶賛を証拠として何度も足さなくても、うれしいという事実は伝わる。短さは成果を隠すためではなく、称賛の量を相手に要求しないためにある。\n実績を正確に説明すべき面接や報告の場と、友人との日常会話は分ける。日常では、何を達成したかより、なぜうれしかったかを一つ話す方が共感につながる。相手の表情や質問が細くなったら情報を追加せず、話題を開く。自慢をゼロにするのではなく、相手が観客に固定される前に終えられることが大切である。","status":"draft","access_tier":"free","updated_at":"2026-09-04 14:51:17.35991+00"},{"id":"master336-341","title":"相手の成功に水を差さない","essence":"喜んでいる相手に欠点や現実論を足すと、祝福ではなく採点になる。","explanation":"良い知らせを話す人は、分析会議より喜びの共有を求めていることが多い。そこで「でも忙しくなるよ」「もっと上もいる」と欠点を足すと、相手は喜んだ自分が浅かったかのように感じる。感情を引っ込め、こちらの前では浮かれすぎないよう自己監視を始めるため、祝ってほしかった会話が評価者への報告に変わる。\n友人が転職の内定を喜んでいるなら、まず「おめでとう。頑張っていたものね」と一緒に喜ぶ。条件上の心配が本当にある場合も、その瞬間に差し込まず、「落ち着いたら条件も一緒に確認する？」と別の時間へ分ける。成功を祝う局面とリスクを検討する局面を混ぜないだけで、相手は喜びを守ったまま現実も考えられる。\n無条件に賛成し、危険を見ないふりをする必要はない。違いは、相手の感情を受け取る前に採点を始めないことにある。良い報告には関心を示し、工夫や努力を具体的に尋ねる。必要な助言は許可とタイミングを選ぶ。祝福を先に完了させれば、現実的な話も対立ではなく支援として届きやすい。","status":"draft","access_tier":"free","updated_at":"2026-09-04 14:51:17.35991+00"},{"id":"master336-342","title":"知らないことを馬鹿にしない","essence":"知識差を優劣に変えると、相手は質問も発言もしづらくなる。","explanation":"「そんなことも知らないの」という反応は、一つの知識不足を人全体の能力評価へ広げる。相手は答えを得る前に恥を処理し、次からは分からないことを隠すようになる。冗談の形でも、質問すれば地位を下げられるという学習が残るため、会話の安全性が失われ、互いに確かめられるはずの情報まで閉じていく。\n相手が基本的な用語を知らなければ、「これはこういう意味だよ」と説明し、どこから知りたいかを聞く。「常識」「普通は知っている」を前置きにしない。自分が詳しい理由も、仕事や趣味で触れる機会が多かったからだと文脈に戻せば、知識差を才能や格の差にしなくて済む。質問への第一反応を穏やかにするだけで、相手は会話へ残れる。\n説明する側が何でも教える義務を負うわけではない。時間がなければ資料を示したり、後で話すと伝えたりしてよい。大切なのは、知らないことを境界設定の理由にはしても、侮辱の材料にしないことだ。質問しても尊厳を失わない関係では、誤解が早く見つかり、こちらも知らないと言いやすくなる。","status":"draft","access_tier":"free","updated_at":"2026-09-04 14:51:17.35991+00"},{"id":"master336-343","title":"相手の選択を採点しない","essence":"恋愛・仕事・服・趣味まで評価すると、会話が交流ではなく審査になる。","explanation":"「それは正解」「その服はなし」のように、頼まれていない選択まで点数化すると、こちらが基準を持つ審査員になる。相手は自分の好みや事情を話す代わりに、こちらの合格条件を推測し始める。親しさの中で評価が続くほど、自分で選ぶ感覚と自然な自己開示が削られ、会うたびに失点を避ける心理的負担が増える。\n友人が新しい趣味や服を見せたら、「自分なら選ばない」ではなく、「どこが気に入ったの？」と本人の基準を聞く。意見を求められた場合も、「私の好みではこちら。ただ、あなたが重視しているのは何？」と主語を限定する。選択の背景を知る前に結論を置かないだけで、会話は採点から理解へ戻る。\n健康、安全、金銭など重大な影響がある選択では、懸念を伝える必要もある。ただし人格やセンスの判定にせず、観察できる事実と自分の心配を分ける。相手の決定権まで奪わず、助言が必要かを確かめる。意見を持つことと、関係の中で常に採点権を持つことは別である。 相手は自分の選択を話すたびに、承認を申請する構図へ置かれてしまう。","status":"draft","access_tier":"free","updated_at":"2026-09-04 14:51:17.35991+00"},{"id":"master336-344","title":"「だから言った」を言わない","essence":"失敗した相手への結果論は、助言よりも自分の正しさの証明として伝わりやすい。","explanation":"結果が出た後は、以前の助言が明白な正解だったように見えやすい。「だから言った」は問題の解決より、こちらが正しく相手が間違っていたという順位を確定する言葉になる。すでに損失や後悔を抱える相手へ、恥と謝罪の処理まで追加するため、相談しても弱みを使われるという警戒が残る。\n友人が心配していた選択で失敗したら、「今いちばん困っているのは何？」と現在へ焦点を移す。以前の助言を確認する必要がある場合も、「次はどの兆候を見たら止まれそう？」と再発防止の条件へ変換する。過去の発言記録を証拠として突きつけず、相手が次に使える情報だけを残す。\n自分の助言が繰り返し無視され、後始末だけ求められるなら、支援の範囲に境界線を引いてよい。正しさを示さないことは、無制限に救済することではない。「今回はここまでなら手伝える」と責任を分ける。失敗直後に勝敗を決めず、学習と負担の分担を別々に扱う方が関係を対等に保てる。 しかも結果が出る前に存在した不確実さまで、後から見えなくなりやすい。","status":"draft","access_tier":"free","updated_at":"2026-09-04 14:51:17.35991+00"},{"id":"master336-345","title":"愚痴の聞き役を固定しない","essence":"同じ相手に感情処理を任せ続けると、友情が感情労働に変わる。","explanation":"話を聞いてもらうことは支えになるが、毎回同じ人を受け皿にすると役割が固定される。聞き手は自分が疲れていても機嫌を整え、共感し、言葉を選び、会話を安全に終える仕事を担う。断れば冷たい人になる不安まで生じるため、表面上は応じていても、友情の中に一方的な感情労働と義務感が蓄積する。\n重い話を始める前に、「十分だけ聞ける？今日は無理なら大丈夫」と受け取れる状態を確認する。家族、別の友人、相談窓口、ノートなど、話す先と処理方法を一つに集中させない。聞いてもらった後は相手の近況も尋ね、次回は楽しい話や共同の時間をつくる。支えを分散することは、関係を薄くするのではなく守る工夫である。\n支え合いを毎回同じ量で返す必要はなく、つらい時期に偏ることもある。ただし、相手の同意と余力を確認せず恒常的な役割にしない。専門的な支援が必要な状態を友人一人で抱えないことも大切である。好意で聞いてくれる人ほど限界を言いにくいと考え、断れる出口をこちらから用意する。 聞き手の沈黙もまた、休める時間として尊重する。","status":"draft","access_tier":"free","updated_at":"2026-09-04 14:51:17.35991+00"},{"id":"master336-346","title":"同じ愚痴を何度も持ち込まない","essence":"解決しない話を反復すると、相手に同じ負担を繰り返し背負わせる。","explanation":"同じ不満を話すと一時的に軽くなるが、聞き手はそのたびに状況を思い出し、怒りや悲しみに同調し、以前と違う反応まで探す。話し手に変化も目的もないまま反復されると、相手は助けられない無力感と、また始まるかもしれない警戒を持つ。愚痴の負担は一回の長さだけでなく、終わりが見えない予測不能さからも生まれる。\n同じ話をしたくなったら、「前にも話した件で、今日は結論を出したい」「五分だけ吐き出したい」と目的と時間を先に示す。前回から新しい事実も行動もないなら、まず紙に書く、散歩する、当事者へ伝える準備をするなど別の処理を試す。相手に話すときは、何が変わったかを一つ添えると、同じ感情の再放送になりにくい。\n繰り返し話すことが必要な喪失や被害もあり、回数だけで責めるべきではない。ただし、その場合ほど相手の同意を取り、友人以外の支援も確保する。聞いてもらうことを解決の代わりにせず、変えられる問題なら小さな行動へ、変えられない問題なら感情を整える方法へつなぐ。","status":"draft","access_tier":"free","updated_at":"2026-09-04 14:51:17.35991+00"},{"id":"master336-347","title":"自虐で相手にフォローさせない","essence":"自分を下げ続けると、相手に否定と励ましを繰り返させることになる。","explanation":"自虐は場を和ませることもあるが、「自分なんて価値がない」を繰り返すと、相手は笑えば傷つけ、黙れば同意したように見えるため、毎回否定して励ますしかなくなる。話し手は低い位置を取っているようで、実際には相手の反応を強く拘束している。会話のたびに自己評価を支える感情労働を求められると、親しさより緊張が残る。\n失敗を話すなら、「私は本当に駄目」ではなく、「準備が足りなくて今回は失敗した」と出来事へ限定する。照れ隠しなら、「褒められると照れるけどうれしい」と感情をそのまま言う。もし自己否定への意見が欲しいなら、「今は励ましがほしい」と依頼に変えれば、相手は何を返すべきか推測せずに済む。\n一度の自虐や互いに合意した軽い冗談まで禁止する必要はない。注意したいのは、同じ否定を何度も提出し、相手の肯定でしか会話を終えられない形である。深い自己否定が続くなら、友人の即席の励ましだけに頼らず、休養や専門的な相談も考える。相手の好意を、自分の価値を毎回証明する義務に変えない。","status":"draft","access_tier":"free","updated_at":"2026-09-04 14:51:17.35991+00"},{"id":"master336-348","title":"相談では共感と助言を分ける","essence":"相手が求めているものを外すと、善意でも会話は負担になる。","explanation":"相談には、気持ちを分かってほしい時と、選択肢を整理したい時がある。共感を求める相手へ解決策を並べると、「その程度も考えていない」と能力を低く見られた感覚が生まれる。反対に具体策が必要な相手へ相づちだけを返すと、問題を一人で処理する負担が残る。善意の量より支援の種類の不一致が疲れを生む。\n話を聞き始めるときに、「今日は聞いてほしい感じ？一緒に考える感じ？」と二択で確かめる。途中で変わることもあるので、「ここから案を出してもいい？」と切り替え点を置く。共感なら感情や意味を要約し、助言なら前提、選択肢、次の一歩を整理する。同じ会話でも役割を分ければ、相手は不要な反論や説明を減らせる。\n相手自身が何を求めているか分からないこともある。そのときはまず短く受け止め、急いで決めなくてよい。共感は全面賛成ではなく、助言は決定権の取得でもない。聞く段階と考える段階を区切り、最終的に選ぶのは相手だと保つことで、支援が管理や放置へ傾くのを防げる。 役割が見えるだけで、互いの認知負荷も下がる。","status":"draft","access_tier":"free","updated_at":"2026-09-04 14:51:17.35991+00"},{"id":"master336-349","title":"求められていない助言を押しつけない","essence":"正しい助言でも、頼まれていなければ管理や干渉として伝わる。","explanation":"助言は内容だけでなく、「あなたの判断には修正が必要だ」という関係上のメッセージも運ぶ。頼まれていない場面で正解を示すと、相手は事情を説明して自分を弁護するか、従わない理由を示す仕事を負う。善意でも選択権を狭められた感覚が生まれ、正しさが強いほど反発や無力感につながりやすい。\n友人が仕事の不満を話したとき、すぐ「転職すべき」と結論を出さず、「意見がほしい？今日は聞くだけがいい？」と確認する。役立ちそうな情報があるなら、「一つ案があるけど聞く？」と入口を渡す。断られたら理由を追わず、話を戻す。許可があれば、命令ではなく選択肢として短く提示する。\n緊急の危険や他者への重大な被害がある場合は、頼まれていなくても伝える必要がある。それ以外では、助言したい衝動と相手の必要を分ける。情報を差し出すことはできても、採用の決定は相手に残す。自律性を守った助言は、相手が必要な時に再び相談できる関係も守る。 相手が黙るのは納得ではなく、反論を諦めた結果かもしれない。","status":"draft","access_tier":"free","updated_at":"2026-09-04 14:51:17.35991+00"},{"id":"master336-350","title":"機嫌を察してもらおうとしない","essence":"不機嫌を言葉にせず示すと、周囲に原因探しと感情監視をさせる。","explanation":"返事を短くする、物音を強くする、ため息をつくといった不機嫌の表示は、要求を言わずに周囲へ解読を求める。相手は自分が原因か、何を直せば安全かを推測し、表情や声の変化を監視し続ける。理由が分からないほど責任の範囲も見えず、一人の感情を全員で管理するような緊張が生まれる。\n余裕がないなら、「今日は仕事で疲れていて静かにしたい。あなたのせいではない」と短く言う。相手にしてほしいことがある場合は、「十分だけ一人にしてほしい」「明日話したい」と具体的に依頼する。すぐ言葉にできないときも、「まだ整理できないけれど、後で説明する」と期限を置けば、相手は無限に原因を探さずに済む。\n感情を常に明るく整える必要はない。不機嫌になる自由と、その処理を周囲へ無言で委ねない責任を分ける。強い感情の最中は距離を置き、落ち着いてから観察、感情、必要、依頼を言葉にする。説明は相手に機嫌を直させる命令ではなく、責任の所在と次の行動を共有するために行う。 予告のない機嫌の変化は、次の変化への警戒まで習慣化させる。","status":"draft","access_tier":"free","updated_at":"2026-09-04 14:51:17.35991+00"},{"id":"master336-351","title":"「察して」を関係の前提にしない","essence":"言葉にしない要求が増えるほど、親しさは気楽さではなく緊張に変わる。","explanation":"親しいなら分かるはずだと思うほど、要望を言葉にせず試す場面が増える。しかし相手は同じ情報も感覚も持っておらず、外せば愛情不足として責められる。正解が明示されない試験が続くと、相手は会話の内容より声色や沈黙から隠れた要求を探すようになり、親しさが常時の注意力を求める関係へ変わる。\n誕生日の過ごし方、連絡頻度、疲れている時の接し方など、期待があることほど具体的に伝える。「言わなくてもしてほしい」ではなく、「今夜は話を聞いてほしい」「返信は明日で大丈夫」のように、望みと余白を一緒に示す。相手が外した後に答えを明かすのではなく、外す前に共有する方が互いの自由時間と安心を守れる。\n全部を説明しなくても通じる喜びは、親しさの結果として楽しめばよい。ただし、それを愛情の証明条件にはしない。伝えた上で応じるかどうかは相手にも選択権がある。察知の精度ではなく、要望を安全に言え、断りや調整もできることを関係の強さと考える。 明文化されない基準は、成功しても次の試験を終わらせない。","status":"draft","access_tier":"free","updated_at":"2026-09-04 14:51:17.35991+00"},{"id":"master336-352","title":"相手の悩みを勝手に小さくしない","essence":"他人や自分と比較して軽く扱うと、相手は悩みより話したことを後悔する。","explanation":"「もっと大変な人がいる」「自分の時は平気だった」は、悩みの強さを比較で判定する言葉である。相手が感じた苦しさより、こちらの基準を上に置くため、相手は出来事に加えて「この程度でつらい自分は弱い」という恥まで抱える。相談の場が理解ではなく苦しさの資格審査になると、次から助けを求めにくくなる。\n相手が試験や失恋で落ち込んでいたら、規模を評価せず、「あなたにとって大きかったんだね」「何が一番つらい？」と本人の意味を聞く。視野を広げる話が役立ちそうでも、まず受け止めた後に「別の見方も一緒に考える？」と確認する。自分の経験は基準ではなく、理解の仮説として限定して使う。\n受容は、事実関係や危険度を誇張することではない。感情の存在を認めることと、状況を評価することを分ける。相手の悩みを唯一最大のものと扱わなくても、その人に生じている負担は尊重できる。比較で早く閉じず、必要なら具体的な支援へつなぐ方が、相手の尊厳と問題解決の両方を守れる。 苦しさを比べずに聞くことが、必要な支援を見つける入口になる。","status":"draft","access_tier":"free","updated_at":"2026-09-04 14:51:17.35991+00"},{"id":"master336-353","title":"いじりに相手の弱点を使わない","essence":"場が笑っても、本人には次も狙われるという警戒が残る。","explanation":"見た目、失敗、家庭、恋愛など本人が守りたい弱点を笑いにすると、その場では本人も合わせて笑うことがある。拒めば空気を壊す人にされるため、笑顔は同意の証拠にならない。周囲の笑いが報酬になる一方、本人には「また材料にされる」という予測が残り、発言や自己開示を控える心理的安全性の低下につながる。\n冗談にするなら、その場の出来事や自分自身など、相手の尊厳と長く結びつかない対象を選ぶ。相手が以前笑った話でも、人前で繰り返す前に「これ話して大丈夫？」と確認する。表情が固まる、弁解が増える、急に静かになるといった変化があれば、笑いを重ねずすぐ話題を止め、短く謝る。\nいじりが成立する関係もあるが、対等に断れ、互いに同程度に返せ、後へ傷が残らないことが条件である。「冗談が通じない」で責任を相手へ移さない。盛り上がりの利益を得る人と、尊厳の費用を払う人が分かれていないかを見る。迷う弱点は使わない方が、安心して笑える範囲は広がる。 笑いが起きた事実より、本人がその場を離れた後も安心できるかを見る。","status":"draft","access_tier":"free","updated_at":"2026-09-04 14:51:17.35991+00"},{"id":"master336-354","title":"人前で相手を下げない","essence":"第三者の前でのからかいや暴露は、冗談以上に立場を傷つける。","explanation":"二人なら流せる指摘でも、第三者の前では評価と記憶が加わる。失敗や秘密を笑いにすると、本人は内容への反応だけでなく、周囲からどう見られたか、訂正すれば場がどうなるかまで同時に処理する。公の場で失った面子はその場の謝罪だけでは戻りにくく、次の集まりでも立場を守る警戒が続く。\n直したいことがあるなら、緊急性がない限り二人の時に事実と要望を伝える。集まりで相手の失敗談を話したくなったら、本人が自分で話しているか、共有範囲に同意しているかを確かめる。誰かが相手を下げた場合は、便乗せず話題を戻すか、その人の貢献を事実として補い、笑いの集中を切る。\n危険を止める、誤情報を訂正するなど、人前で言う必要がある場面はある。その場合も人格を下げず、対象となる行動や事実に限定する。注意と見せしめを混ぜない。相手が反論しにくい観客のいる場所で優位を取らず、尊厳を保ったまま修正できる出口を残す。 観客が増えるほど、本人がその場で示せる反応の自由も小さくなり、傷を隠す負担まで増える。","status":"draft","access_tier":"free","updated_at":"2026-09-04 14:51:17.35991+00"},{"id":"master336-355","title":"親しさを免罪符にしない","essence":"仲がいいほど雑に扱ってよいわけではなく、小さな無礼ほど蓄積する。","explanation":"親しい関係では、一度の遅刻や雑な返事を許してもらえることがある。しかし許容を権利だと受け取ると、謝罪、感謝、確認が省かれ、相手だけが飲み込む役になる。「仲がいいから」という言葉で異議も封じられるため、小さな無礼は出来事以上に、尊重されていない感覚として静かに蓄積する。\n家族や古い友人にこそ、予定を変えたら連絡し、してもらったことには短く感謝する。以前は平気だった冗談や連絡頻度も、環境が変われば受け取り方が変わるので、ときどき「今も大丈夫？」と確かめる。相手が不満を言ったときは、親しさの証明を求めず、何を変えるかを具体的に返す。\n形式ばった距離を置く必要はなく、気楽さは親しさの価値である。ただし気楽さは、相手がいつでも断れ、雑さを指摘しても関係を脅かされないときに成り立つ。親しさを配慮の省略許可ではなく、率直に調整できる土台として使う。近い相手ほど、礼儀を大きな儀式ではなく小さな確認として残す。 過去の近さは、現在の同意を自動的に更新するものではない。","status":"draft","access_tier":"free","updated_at":"2026-09-04 14:51:17.35991+00"},{"id":"master336-356","title":"好意に見返りを求めない","essence":"「これだけしたのに」が増えるほど、好意は相手にとって借金になる。","explanation":"親切の後で反応や返礼を当然視すると、受け手には知らないうちに契約へ参加させられた感覚が残る。感謝の量、連絡頻度、次の手助けまで採点されるため、好意を受け取るたびに将来の返済を計算するようになる。「断れば恩知らず」と思わせる関係では、贈り物や支援そのものが心理的な債務と統制手段へ変わる。\n何かをする前に、返ってこなくても自分が納得できる範囲かを確かめる。返礼が必要な貸し借りや分担なら、好意の形に隠さず「次回はお願いしたい」と先に合意する。期待が生まれた後も、「してあげたのに」と請求する前に、自分の希望として言葉にし、相手が断れる余地を残す。\n互恵性そのものは関係を支えるため、いつも一方だけが与える必要はない。偏りが続いて苦しいなら、提供を減らす、役割を話し合う、距離を調整する。大切なのは、無条件の好意と条件付きの交換を混ぜないことだ。見返りを求めるなら最初から合意にし、好意として渡したものを後から請求書へ変えない。 受け取る側が安心して断れることも、好意の一部である。","status":"draft","access_tier":"free","updated_at":"2026-09-04 14:51:17.35991+00"}]'::jsonb)
 as expected(id text,title text,essence text,explanation text,status text,access_tier text,updated_at timestamptz)
 join public.techniques t using(id)
 where t.title=expected.title and t.essence=expected.essence and t.explanation=expected.explanation
 and t.status=expected.status and t.access_tier=expected.access_tier and t.updated_at=expected.updated_at) <> 22
 then raise exception 'Target content changed after review; aborting repair'; end if;
 if not exists(select 1 from public.personas where name='一緒にいて疲れない人' and status='published' and access_tier='complete')
 then raise exception 'Persona publication or edition changed'; end if;
end $repair$;
update public.techniques t set explanation=corrected.explanation,updated_at=now()
from jsonb_to_recordset('[{"id":"master336-309","title":"進んだ道を正解にする覚悟を持つ","essence":"選択の正解は、選んだ瞬間より、その後どう生きたかで変わる。","explanation":"選択した瞬間に、その道が正解かどうかを確定することはできない。未来には予想外の出来事があり、同じ選択でも置かれた環境によって結果が変わるからだ。そこで「正しい道を選べたか」だけを気にすると、少し悪い結果が出るたびに選択そのものを疑うことになる。一方、選んだ後に経験を積み、工夫し、結果を作っていけば、当初は迷いのあった道にも意味が生まれる。\nたとえば、転職した会社で最初から理想の仕事ができるとは限らない。期待していた部署と違ったり、上司との相性が悪かったりして、「前の会社に残った方がよかった」と思う時期もあるだろう。しかし、そこで新しい業務を覚え、人脈を作り、異動や役割変更を働きかけた結果、数年後には以前より自分に合う仕事を任されることもある。転職した瞬間の判断だけを切り取れば、その後に作った成果は評価できない。\n実用上は、決断後すぐに「正解だったか」を採点し続けるより、「この選択をした以上、何を改善できるか」を考える方が生産的である。もちろん、明らかに合わない環境から撤退することまで否定する話ではない。重要なのは、少し不都合が起きただけで、別の道を選んでいれば成功していたと考えないことだ。選んだ道には、その後の行動によって変えられる部分が残っている。"},{"id":"master336-310","title":"過去の自分を今の情報だけで裁かない","essence":"今なら分かることを、当時の自分も知っていた前提で責めるのはフェアではない。","explanation":"現在の自分には、過去にはなかった情報や経験がある。そのため、今なら避けられる失敗を見つけると、「なぜあのとき分からなかったのか」と過去の自分を責めやすい。しかし当時の判断材料には、現在知っている事実が存在していなかった。後から結果を知った状態で過去の判断を評価すると、最初から結末を知っていたかのような比較になる。\nたとえば、以前の会社を辞めた直後に業界の景気が悪化し、「あの時点で残っていればよかった」と後悔する場合がある。今から見ると景気悪化の兆候は明らかに思えるかもしれない。しかし退職を決めた時点では、その後の市場環境も、転職先の状況も確定していなかった。手元にあった情報を使って考えた結果なら、結果が悪かったことと判断が愚かだったことは同じではない。後から得た答えを、当時の自分に持たせてはいけない。\n実用上は、過去の判断を振り返る際に「その時点で何を知っていたか」を先に確認するとよい。そのうえで、判断の過程に改善できる点があれば、現在の自分の知識として回収する。「次はここを確認する」と学習へ変えれば、過去の失敗は現在の判断精度を上げる材料になる。一方、「あのとき分かっていれば」と繰り返しても、当時には存在しなかった情報を追加することはできない。"}]'::jsonb) as corrected(id text,title text,essence text,explanation text)
where t.id=corrected.id;
update public.techniques set status='published',access_tier='complete',
 display_order=draft_display_order,draft_display_order=null,updated_at=now()
where persona_id='一緒にいて疲れない人' and id in ('master336-337','master336-338','master336-339','master336-340','master336-341','master336-342','master336-343','master336-344','master336-345','master336-346','master336-347','master336-348','master336-349','master336-350','master336-351','master336-352','master336-353','master336-354','master336-355','master336-356');
do $verify$
begin
 if (select count(*) from public.techniques where status='published')<>356
 or (select count(*) from public.techniques where status='published' and access_tier='free')<>95
 or (select count(*) from public.public_techniques where persona_id='一緒にいて疲れない人' and access_tier='complete')<>20
 or (select count(*) from public.techniques where persona_id='一緒にいて疲れない人' and status='published' and display_order between 1 and 20)<>20
 or (select count(distinct display_order) from public.techniques where persona_id='一緒にいて疲れない人' and status='published')<>20
 or (select count(*) from public.techniques t join public.paid_content p on p.content_type='technique' and p.content_id=t.id
 where t.id in ('master336-309','master336-310','master336-337','master336-338','master336-339','master336-340','master336-341','master336-342','master336-343','master336-344','master336-345','master336-346','master336-347','master336-348','master336-349','master336-350','master336-351','master336-352','master336-353','master336-354','master336-355','master336-356') and p.payload->>'explanation'=t.explanation and p.payload->>'essence'=t.essence)<>22
 then raise exception 'Published or complete-edition verification failed'; end if;
end $verify$;
commit;
select jsonb_build_object('publishedTechniques',(select count(*) from public.techniques where status='published'),
 'freeTechniques',(select count(*) from public.techniques where status='published' and access_tier='free'),
 'fatiguePersonaTechniques',(select count(*) from public.public_techniques where persona_id='一緒にいて疲れない人'),
 'correctedExplanations',(select jsonb_agg(jsonb_build_object('id',id,'title',title,'opening',split_part(explanation,'。',1))) from public.techniques where id in ('master336-309','master336-310'))) as result;
